/* Generated from the four local App demo thumbnails; no cross-app media dependency. */
window.AppPrototypeMedia=Object.freeze({"thumb-living.jpg":"data:image/jpeg;base64,","thumb-video.jpg":"data:image/jpeg;base64,","thumb-community.jpg":"data:image/jpeg;base64,","thumb-skyline.jpg":"data:image/jpeg;base64,"});
function appMedia(value,fallback='thumb-living.jpg'){const src=String(value||'');if(src.startsWith('data:')||src.startsWith('blob:'))return src;let name=src.split(/[?#]/)[0].split('/').pop();try{name=decodeURIComponent(name)}catch{}return window.AppPrototypeMedia[name]||src||window.AppPrototypeMedia[fallback]||''}
